schemaSql:
CREATE TABLE riders (
  rider_id INT PRIMARY KEY,
  name TEXT NOT NULL,
  city TEXT NOT NULL
);
CREATE TABLE ride_bookings (
  booking_id INT PRIMARY KEY,
  rider_id INT, -- NULL for guest bookings
  ride_date DATE NOT NULL
);

